const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 900 });
  const url = 'file:///workspace/AI%20%E5%B7%A5%E4%BD%9C%E5%8C%BA/%E6%88%90%E6%9E%9C%E6%96%87%E4%BB%B6/%E6%A0%B9%E6%8D%AE%E8%BF%99%E4%BB%BD%E4%BB%8B%E7%BB%8D%EF%BC%8C%E5%B8%AE%E6%88%91%E6%90%93%E4%B8%80%E4%B8%AAhtml%E7%9A%84%E9%A6%96%E9%A1%B5-conv_4a2da8d3a8da/2026-08-04_TTFA%E9%A6%96%E9%A1%B5.html';
  await page.goto(url, { waitUntil: 'networkidle0', timeout: 30000 });
  // 等数字滚动和入场动画完成
  await new Promise(r => setTimeout(r, 2500));

  // 全页截图
  await page.screenshot({ path: 'fullpage.png', fullPage: true });

  // 控制台错误收集
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(String(e)));

  // 检查关键区块是否渲染（取文本内容验证）
  const checks = await page.evaluate(() => {
    const has = (sel) => !!document.querySelector(sel);
    const txt = (sel) => { const el = document.querySelector(sel); return el ? el.innerText.slice(0, 60).replace(/\n/g, ' ') : '(missing)'; };
    return {
      hero_title: txt('.hero h1'),
      stats_done: [...document.querySelectorAll('.stat b')].map(b => b.textContent),
      pain_cards: [...document.querySelectorAll('.pain-card h3')].map(h => h.textContent),
      value_title: txt('.value-block h3'),
      modules: [...document.querySelectorAll('.mod-card h3')].map(h => h.textContent),
      roadmap: [...document.querySelectorAll('.rm-item h4')].map(h => h.textContent),
      tech_cards: [...document.querySelectorAll('.tech-card h3')].map(h => h.textContent),
      pyramid: [...document.querySelectorAll('.py-row h4')].map(h => h.textContent),
      team: [...document.querySelectorAll('.team-card h3')].map(h => h.textContent),
      honors: document.querySelectorAll('.honor').length,
      papers: document.querySelectorAll('.paper').length,
      reveal_visible: [...document.querySelectorAll('.reveal')].filter(r => r.classList.contains('in')).length,
      reveal_total: document.querySelectorAll('.reveal').length,
      body_scroll_height: document.body.scrollHeight,
    };
  });
  console.log('=== 区块检查 ===');
  console.log(JSON.stringify(checks, null, 2));
  console.log('=== 控制台错误 ===');
  console.log(errors.length ? errors.join('\n') : '无');
  await browser.close();
})();

